SELECT a.* FROM b_sanliuling_pp_data a LEFT JOIN b_sanliuling_pp_data b ON a.mobile_no_md5 = b.mobile_no_md5 AND b.push_status = 2 AND b.create_date = DATE_FORMAT(now(), '%Y%m%d') WHERE a.local_id = #{localId} AND a.status = 1 AND a.push_status = 1 AND b.mobile_no_md5 IS NULL
AND a.id > #{minId}
ORDER BY a.id ASC LIMIT 2000

